<?php
namespace App\Http\Controllers;
use App\Models\{Product,StockIn,StockOpname,StockOut,Supplier}; use App\Services\StockService; use Illuminate\Http\Request;
class StockController extends Controller { public function __construct(private StockService $service){} public function history(){return view('stock.history',['ins'=>StockIn::with(['product','supplier','user'])->latest('date')->get(),'outs'=>StockOut::with(['product','user'])->latest('date')->get(),'opnames'=>StockOpname::with(['product','user'])->latest('date')->get()]);} public function createIn(){return view('stock.in-form',['products'=>Product::orderBy('name')->get(),'suppliers'=>Supplier::orderBy('name')->get()]);} public function storeIn(Request $r){$this->service->incoming($r->validate(['product_id'=>'required|exists:products,id','supplier_id'=>'nullable|exists:suppliers,id','quantity'=>'required|integer|min:1','date'=>'required|date','note'=>'nullable']),$r->user());return redirect()->route('stock.history')->with('success','Barang masuk dicatat.');} public function createOut(){return view('stock.out-form',['products'=>Product::orderBy('name')->get()]);} public function storeOut(Request $r){$this->service->outgoing($r->validate(['product_id'=>'required|exists:products,id','quantity'=>'required|integer|min:1','date'=>'required|date','reason'=>'nullable|max:150','note'=>'nullable']),$r->user());return redirect()->route('stock.history')->with('success','Barang keluar dicatat.');} public function createOpname(){return view('stock.opname-form',['products'=>Product::orderBy('name')->get()]);} public function storeOpname(Request $r){$this->service->opname($r->validate(['product_id'=>'required|exists:products,id','physical_stock'=>'required|integer|min:0','date'=>'required|date','note'=>'nullable']),$r->user());return redirect()->route('stock.history')->with('success','Stock opname disimpan.');} public function confirmIn($id, Request $r){$this->service->confirmIncoming($id, $r->user());return redirect()->route('stock.history')->with('success','Barang masuk dikonfirmasi.');} public function confirmOut($id, Request $r){$this->service->confirmOutgoing($id, $r->user());return redirect()->route('stock.history')->with('success','Barang keluar dikonfirmasi.');} }
